    <div className={`flex-shrink-0 w-6 h-6 transition-colors ${isActive ? 'text-primary-foreground' : 'text-brand-text-secondary group-hover:text-brand-text-primary'}`}>{icon}</div>
    {!isCollapsed && <span className="ms-3">{label}</span>}
