export const ThemeToggle = () => {
    const { t } = useTranslation();
    const [theme, setTheme] = useState<'light' | 'dark'>(() => {
        if (typeof window !== 'undefined') {
            return document.documentElement.classList.contains('dark') ? 'dark' : 'light';
        }
        return 'dark';
    });

    useEffect(() => {
        if (theme === 'dark') {
            document.documentElement.classList.add('dark');
            localStorage.setItem('theme', 'dark');
        } else {
            document.documentElement.classList.remove('dark');
            localStorage.setItem('theme', 'light');
        }
    }, [theme]);

    const toggleTheme = () => {
        setTheme(prevTheme => prevTheme === 'dark' ? 'light' : 'dark');
    };

    return (
        <NewThemeToggle 
            theme={theme} 
            toggleTheme={toggleTheme} 
            aria-label={t('header.toggleTheme')} 
        />
    );
};

// --- GLOBAL SEARCH COMPONENT ---
type SearchResult = {
  type: 'contact' | 'workflow';
  name: string;
  details: string;
};

const performSearch = async (query: string): Promise<SearchResult[]> => {
  if (!query) return [];
  try {
    const results = await supabase.searchGlobally(query);
    return results.filter((res: SearchResult) => res.type === 'contact');
  } catch (error) {
    console.error("Search failed:", error);
    return []; // Return empty array on error
  }
};

const GlobalSearch = () => {
    const { t } = useTranslation();
    const [query, setQuery] = useState('');
    const [results, setResults] = useState<SearchResult[]>([]);
    const [isActive, setIsActive] = useState(false);
    const [isLoading, setIsLoading] = useState(false);
    const searchRef = useRef<HTMLDivElement>(null);

    useEffect(() => {
        const handleEsc = (event: KeyboardEvent) => {
            if (event.key === 'Escape') setIsActive(false);
        };
        document.addEventListener('keydown', handleEsc);
        return () => {
            document.removeEventListener('keydown', handleEsc);
        };
    }, []);

    useEffect(() => {
        if (!query.trim()) {
            setResults([]);
            setIsLoading(false);
            return;
        }
        setIsLoading(true);
        const debounceTimer = setTimeout(() => {
            performSearch(query).then(res => {
                setResults(res);
                setIsLoading(false);
            });
        }, 300);
        return () => clearTimeout(debounceTimer);
    }, [query]);

    return (
        <div className="relative hidden lg:block" ref={searchRef}>
            <div className="relative">
                <SearchIcon className="absolute start-3 top-1/2 -translate-y-1/2 h-5 w-5 text-brand-text-secondary pointer-events-none" />
                <Input
                    type="text"
                    placeholder={t('header.searchPlaceholder')}
                    className="w-64 xl:w-96 h-10 ps-10 bg-brand-secondary border-none"
                    value={query}
                    onChange={(e) => setQuery(e.target.value)}
                    onFocus={() => setIsActive(true)}
                />
            </div>

            {isActive && (query || isLoading || results.length > 0) && (
                <div className="absolute top-full mt-2 w-full bg-brand-primary border border-brand-border rounded-lg shadow-lg z-20 max-h-96 overflow-y-auto">
                    <button onClick={() => setIsActive(false)} className="absolute top-2 end-2 p-1.5 rounded-full text-brand-text-secondary hover:bg-brand-secondary z-10">
                        <XIcon className="w-4 h-4" />
                    </button>
                    {isLoading ? (
                        <div className="p-4 text-sm text-brand-text-secondary">{t('header.searching')}</div>
                    ) : results.length > 0 ? (
                        <div className="py-2">
                           <div>
                                <h3 className="text-xs font-semibold text-brand-text-secondary uppercase px-4 py-2">{t('header.contacts')}</h3>
                                <ul>
                                    {results.map((res, i) => (
                                        <li key={`contact-${i}`}>
                                            <button className="w-full text-left px-4 py-2 flex items-center gap-3 hover:bg-brand-secondary">
                                                <Avatar name={res.name} className="w-8 h-8"/>
                                                <div>
                                                    <p className="text-sm font-medium text-brand-text-primary">{res.name}</p>
                                                    <p className="text-xs text-brand-text-secondary">{res.details}</p>
                                                </div>
                                            </button>
                                        </li>
                                    ))}
                                </ul>
                            </div>
                        </div>
                    ) : (
                        <div className="p-4 text-sm text-brand-text-secondary">{t('header.noResults', { query })}</div>
                    )}
                </div>
            )}
        </div>
    );
};

interface HeaderProps {
    onMenuClick?: () => void;
    activeView: ActiveView;
    session: Session;
}

export const Header: React.FC<HeaderProps> = ({ onMenuClick, activeView, session }) => {
  const { addToast } = useToast();
  const { t } = useTranslation();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  const handleSignOut = async () => {
      const { error } = await supabase.auth.signOut();
      if (error) {
          addToast(error.message, { type: 'error' });
      } else {
          addToast(t('dashboard.header.signOutSuccess'), { type: 'info' });
      }
  };

  const getTitle = () => {
    switch (activeView) {
      case 'overview': return t('dashboard.header.hub');
      case 'pipeline': return t('dashboard.header.pipeline');
      case 'contacts': return t('dashboard.header.contacts');
      case 'instagram': return t('dashboard.header.instagram');
      case 'outreach': return t('dashboard.header.outreach');
      case 'workflows': return t('dashboard.header.workflows');
      case 'billing': return t('dashboard.header.billing');
      case 'ai_metrics': return t('dashboard.header.ai_metrics');
      default: return 'Dashboard';
    }
  };
  const title = getTitle();

  return (
    <header className="bg-brand-primary p-4 flex items-center flex-shrink-0 border-b border-brand-border gap-4">
      <div className="flex items-center flex-shrink-0">
        {onMenuClick && (
            <button onClick={onMenuClick} className="lg:hidden me-4 -ms-2 p-2 rounded-full text-brand-text-secondary hover:bg-brand-secondary" aria-label={t('header.openMenu')}>
                <MenuIcon className="h-6 w-6" />
            </button>
        )}
        <h1 key={title} className="text-2xl font-bold text-brand-text-primary animate-in">{title}</h1>
      </div>

      <div className="flex-1 flex justify-center">
        <GlobalSearch />
      </div>

      <div className="flex items-center space-x-2 md:space-x-4 flex-shrink-0">
        <LanguageSwitcher />
        <ThemeToggle />
        <div className="relative" ref={dropdownRef}>
            <button onClick={() => setIsDropdownOpen(!isDropdownOpen)} className="flex items-center cursor-pointer">
                <Avatar name={session.user?.email || 'User'} className="h-9 w-9" />
                <div className="ms-3 text-sm hidden sm:block text-start">
                    <p className="font-semibold text-brand-text-primary truncate max-w-xs">{session.user?.email}</p>
                    <p className="text-brand-text-secondary">{t('dashboard.header.administrator')}</p>
                </div>
            </button>
            {isDropdownOpen && (
                <div className="absolute top-full end-0 mt-2 w-56 bg-brand-primary border border-brand-border rounded-lg shadow-lg z-20 py-1">
                    <button onClick={() => setIsDropdownOpen(false)} className="absolute top-1 end-1 p-1.5 rounded-full text-brand-text-secondary hover:bg-brand-secondary">
                        <XIcon className="w-4 h-4" />
                    </button>
                    <div className="px-3 py-2 border-b border-brand-border mt-6">
                        <p className="text-sm font-semibold text-brand-text-primary">{t('dashboard.header.signedInAs')}</p>
                        <p className="text-sm text-brand-text-secondary truncate">{session.user?.email}</p>
                    </div>
                    <button onClick={handleSignOut} className="w-full text-start flex items-center gap-2 px-3 py-2 text-sm font-medium text-destructive hover:bg-destructive/10 rounded-md m-1">
                        <LogoutIcon className="h-4 w-4 text-destructive" />
                        {t('dashboard.header.signOut')}
                    </button>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

