        {onMenuClick && (
            <button onClick={onMenuClick} className="lg:hidden p-2 rounded-full text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors" aria-label={t('header.openMenu')}>
                <MenuIcon className="h-6 w-6" />
            </button>
        )}
        <h1 key={title} className="text-xl font-bold text-foreground animate-in tracking-tight">{title}</h1>
      </div>

      <div className="flex-1 flex justify-center max-w-2xl">
        <GlobalSearch />
