            >
                <Avatar name={session.user?.email || 'User'} className="h-8 w-8 ring-2 ring-background" />
                <div className="text-sm hidden sm:block text-start">
                    <p className="font-medium text-foreground text-xs leading-none">{t('dashboard.header.administrator')}</p>
                    <p className="text-muted-foreground text-[10px] leading-none mt-1 max-w-[100px] truncate">{session.user?.email}</p>
                </div>
            </button>
            {isDropdownOpen && (
