@layer base {
  :root {
    /* 
      Premium 'Zinc' Palette & Teal Accent 
      Designed for high contrast and modern aesthetics.
    */
    --background: 0 0% 100%;
    --foreground: 240 10% 3.9%;

    --card: 0 0% 100%;
    --card-foreground: 240 10% 3.9%;

    --popover: 0 0% 100%;
    --popover-foreground: 240 10% 3.9%;

    /* Refined Teal Primary */
    --primary: 173 80% 40%;
    --primary-foreground: 0 0% 98%;

    /* Secondary is a subtle gray */
    --secondary: 240 4.8% 95.9%;
    --secondary-foreground: 240 5.9% 10%;

    --muted: 240 4.8% 95.9%;
    --muted-foreground: 240 3.8% 46.1%;

    --accent: 240 4.8% 95.9%;
    --accent-foreground: 240 5.9% 10%;

    --destructive: 0 84.2% 60.2%;
    --destructive-foreground: 0 0% 98%;

    --border: 240 5.9% 90%;
    --input: 240 5.9% 90%;
    --ring: 173 80% 40%;

    --radius: 0.75rem;

    /* WhatsApp Specific - Light */
    --wa-bg: #EFE7DE; /* Slightly warmer/premium than standard */
    --wa-message-out-bg: #E1FCD7; /* Cleaner green */
    --wa-message-in-bg: #FFFFFF;
    --wa-panel-header-bg: #F0F2F5;
    --wa-text-secondary: #64748B;
  }

  .dark {
    --background: 240 10% 3.9%;
    --foreground: 0 0% 98%;

    --card: 240 10% 3.9%;
    --card-foreground: 0 0% 98%;

    --popover: 240 10% 3.9%;
    --popover-foreground: 0 0% 98%;

    --primary: 173 70% 50%;
    --primary-foreground: 240 5.9% 10%;

    --secondary: 240 3.7% 15.9%;
    --secondary-foreground: 0 0% 98%;

    --muted: 240 3.7% 15.9%;
    --muted-foreground: 240 5% 64.9%;

    --accent: 240 3.7% 15.9%;
    --accent-foreground: 0 0% 98%;

    --destructive: 0 62.8% 30.6%;
    --destructive-foreground: 0 0% 98%;

    --border: 240 3.7% 15.9%;
    --input: 240 3.7% 15.9%;
    --ring: 173 70% 50%;

    /* WhatsApp Specific - Dark */
    --wa-bg: #0B141A;
    --wa-message-out-bg: #005C4B;
    --wa-message-in-bg: #202C33;
    --wa-panel-header-bg: #202C33;
