  }

  * {
    @apply border-border;
  }

  body {
    @apply bg-background text-foreground antialiased;
    font-feature-settings: "rlig" 1, "calt" 1;
  }

  [dir="rtl"] body {
    font-family: 'Tajawal', sans-serif;
  }
}

@layer utilities {
  /* Apple-style Glassmorphism */
  .glass {
    @apply bg-white/70 dark:bg-black/70 backdrop-blur-md border border-white/20 dark:border-white/10;
  }

  /* Refined Glows */
  .btn-primary-glow {
    box-shadow: 0 0 0 0 hsl(var(--primary) / 0.5);
    transition: box-shadow 0.3s ease;
  }
  .btn-primary-glow:hover {
    box-shadow: 0 0 20px -5px hsl(var(--primary) / 0.6);
  }

  /* Smooth Entrance */
  .animate-in {
    animation: enter 0.4s cubic-bezier(0.16, 1, 0.3, 1); /* Elegant easing */
    animation-fill-mode: forwards;
  }

  @keyframes enter {
    from {
      opacity: 0;
      transform: translateY(8px) scale(0.98);
    }
    to {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  /* Scrollbars */
  ::-webkit-scrollbar {
    width: 8px;
    height: 8px;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    @apply bg-muted-foreground/30 rounded-full transition-colors hover:bg-muted-foreground/50;
  }
}

