          addToast(t('dashboard.header.signOutSuccess'), { type: 'info' });
      }
  };

  const getTitle = () => {
    switch (activeView) {
      case 'overview': return t('dashboard.header.hub');
      case 'pipeline': return t('dashboard.header.pipeline');
      case 'contacts': return t('dashboard.header.contacts');
      case 'instagram': return t('dashboard.header.instagram');
      case 'outreach': return t('dashboard.header.outreach');
      case 'workflows': return t('dashboard.header.workflows');
      case 'billing': return t('dashboard.header.billing');
      case 'ai_metrics': return t('dashboard.header.ai_metrics');
      default: return 'Dashboard';
    }
  };
  const title = getTitle();

  return (
    <header className="sticky top-0 z-30 glass border-b border-border/40 px-6 py-3 flex items-center justify-between gap-6 transition-all duration-300">
      <div className="flex items-center gap-4">
        {onMenuClick && (
            <button onClick={onMenuClick} className="lg:hidden p-2 rounded-full text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors" aria-label={t('header.openMenu')}>
                <MenuIcon className="h-6 w-6" />
            </button>
        )}
        <h1 key={title} className="text-xl font-bold text-foreground animate-in tracking-tight">{title}</h1>
      </div>

      <div className="flex-1 flex justify-center max-w-2xl">
        <GlobalSearch />
      </div>

      <div className="flex items-center gap-4">
        <LanguageSwitcher />
        <ThemeToggle />
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)} 
                className="flex items-center gap-3 p-1 pr-3 rounded-full hover:bg-accent/50 transition-colors border border-transparent hover:border-border/50"
            >
                <Avatar name={session.user?.email || 'User'} className="h-8 w-8 ring-2 ring-background" />
                <div className="text-sm hidden sm:block text-start">
                    <p className="font-medium text-foreground text-xs leading-none">{t('dashboard.header.administrator')}</p>
                    <p className="text-muted-foreground text-[10px] leading-none mt-1 max-w-[100px] truncate">{session.user?.email}</p>
                </div>
            </button>
            {isDropdownOpen && (
                <div className="absolute top-full right-0 mt-2 w-56 rounded-xl border border-border bg-popover text-popover-foreground shadow-lg animate-in fade-in-0 zoom-in-95 z-50">
                    <div className="p-2 border-b border-border/50">
