// --- Main Export ---
export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [step, setStep] = useState<DemoStep>('start');
    const [kanbanCardStage, setKanbanCardStage] = useState('New');
    const [showTag, setShowTag] = useState(false);

    const [isWorkflowVisible, setIsWorkflowVisible] = useState(false);
    const [activeNode, setActiveNode] = useState<string|null>(null);

    const stepIndexRef = useRef(0);

    useEffect(() => {
        const runSequence = () => {
            const current = demoSequence[stepIndexRef.current];
            setStep(current.step);
            setActiveNode(null);

            // Specific actions for steps
            if (current.step === 'showWorkflow') setIsWorkflowVisible(true);
            if (current.step === 'triggerActive') setActiveNode('trigger');
            if (current.step === 'action1Active') setActiveNode('action1');
            if (current.step === 'action2Active') { setActiveNode('action2'); setShowTag(true); }
            if (current.step === 'action3Active') { setActiveNode('action3'); setTimeout(() => setKanbanCardStage('Contacted'), 300); }
            if (current.step === 'action4Active') setActiveNode('action4');

            stepIndexRef.current = (stepIndexRef.current + 1) % demoSequence.length;

            if (stepIndexRef.current === 0) {
                setTimeout(() => {
                   setIsWorkflowVisible(false);
                   setKanbanCardStage('New');
                   setShowTag(false);
                }, 1000);
            }

            setTimeout(runSequence, current.duration);
        };
        const timeoutId = setTimeout(runSequence, 500);
        return () => clearTimeout(timeoutId);
    }, []);

    const messages = useMemo(() => {
        const base = [];
        // Only show messages if past 'start'
        if (stepIndexRef.current > 1) base.push({ sender: 'user', text: t('homepage.demo.chat.u1') });
        if (stepIndexRef.current > 6) base.push({ sender: 'ai', text: t('homepage.demo.chat.a1') });
        if (stepIndexRef.current > 7) base.push({ sender: 'user', text: t('homepage.demo.chat.u2') });
        if (stepIndexRef.current > 11) base.push({ sender: 'ai', text: t('homepage.demo.chat.a2') });
        if (stepIndexRef.current > 12) base.push({ sender: 'user', text: t('homepage.demo.chat.u3') });
        if (stepIndexRef.current > 15) base.push({ sender: 'ai', text: t('homepage.demo.chat.a3') });
        return base;
    }, [step, t]);

    return (
        <div className="w-full max-w-5xl mx-auto h-[600px] md:h-[500px] flex flex-col md:flex-row gap-4 p-2 md:p-4">
            {/* Phone/Chat Interface */}
            <div className="w-full md:w-[45%] h-full bg-white dark:bg-black rounded-[2.5rem] border-[8px] border-zinc-900 dark:border-zinc-800 shadow-2xl overflow-hidden relative flex flex-col">
                {/* Notch/Island area */}
                <div className="absolute top-0 inset-x-0 h-6 bg-transparent z-20 flex justify-center">
                    <div className="w-24 h-5 bg-black rounded-b-xl" />
                </div>

                {/* Chat Header */}
                <div className="pt-8 pb-3 px-4 bg-zinc-50/90 dark:bg-zinc-900/90 backdrop-blur-md border-b border-zinc-200 dark:border-zinc-800 z-10 flex items-center justify-between sticky top-0">
                    <div className="flex items-center gap-3">
                        <Avatar name="Flowtiva Assistant" className="h-8 w-8 ring-2 ring-primary/20" />
