interface HeaderProps {
    onMenuClick?: () => void;
    activeView: ActiveView;
    session: Session;
}

export const Header: React.FC<HeaderProps> = ({ onMenuClick, activeView, session }) => {
  const { addToast } = useToast();
  const { t } = useTranslation();
  const [isDropdownOpen, setIsDropdownOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
      const handleClickOutside = (event: MouseEvent) => {
          if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
              setIsDropdownOpen(false);
          }
      };
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSignOut = async () => {
      const { error } = await supabase.auth.signOut();
      if (error) {
          addToast(error.message, { type: 'error' });
      } else {
          addToast(t('dashboard.header.signOutSuccess'), { type: 'info' });
      }
  };

  const getTitle = () => {
    switch (activeView) {
      case 'overview': return t('dashboard.header.hub');
      case 'pipeline': return t('dashboard.header.pipeline');
      case 'contacts': return t('dashboard.header.contacts');
      case 'instagram': return t('dashboard.header.instagram');
      case 'outreach': return t('dashboard.header.outreach');
      case 'workflows': return t('dashboard.header.workflows');
      case 'billing': return t('dashboard.header.billing');
      case 'ai_metrics': return t('dashboard.header.ai_metrics');
      default: return 'Dashboard';
    }
  };
  const title = getTitle();

  return (
    <header className="sticky top-0 z-30 h-16 glass border-b border-border/40 px-6 flex items-center justify-between gap-6 transition-all duration-300">

      {/* Left: Title & Mobile Menu */}
      <div className="flex items-center gap-4 min-w-[200px]">
        {onMenuClick && (
            <button onClick={onMenuClick} className="lg:hidden p-2 rounded-full text-muted-foreground hover:bg-accent hover:text-accent-foreground transition-colors" aria-label={t('header.openMenu')}>
                <MenuIcon className="h-6 w-6" />
            </button>
        )}
        <div className="flex flex-col justify-center">
            <h1 key={title} className="text-lg font-bold text-foreground animate-in fade-in slide-in-from-left-2 duration-300 tracking-tight leading-none">
                {title}
            </h1>
            {/* Optional Breadcrumb or secondary info could go here */}
        </div>
      </div>

      {/* Center: Search */}
      <div className="flex-1 flex justify-center max-w-xl">
        <GlobalSearch />
      </div>

      {/* Right: Actions & Profile */}
      <div className="flex items-center gap-3 min-w-[200px] justify-end">
        <div className="hidden sm:flex items-center gap-2 pr-2 border-r border-border/50">
            <LanguageSwitcher />
            <ThemeToggle />
            <NotificationButton />
        </div>

        {/* User Dropdown */}
        <div className="relative" ref={dropdownRef}>
            <button 
                onClick={() => setIsDropdownOpen(!isDropdownOpen)} 
                className="flex items-center gap-3 p-1 rounded-full hover:bg-accent/50 transition-all duration-200 border border-transparent hover:border-border/50 focus:outline-none focus:ring-2 focus:ring-ring focus:ring-offset-1"
                aria-haspopup="true"
                aria-expanded={isDropdownOpen}
            >
                <div className="text-right hidden sm:block">
                    <p className="text-xs font-semibold text-foreground leading-tight">{t('dashboard.header.administrator')}</p>
                    <p className="text-[10px] text-muted-foreground leading-tight max-w-[100px] truncate">{session.user?.email}</p>
                </div>
                <Avatar name={session.user?.email || 'User'} className="h-9 w-9 ring-2 ring-background shadow-sm" />
            </button>

            {isDropdownOpen && (
                <div className="absolute top-full right-0 mt-3 w-64 rounded-xl border border-border bg-popover/95 backdrop-blur-md text-popover-foreground shadow-xl animate-in fade-in-0 zoom-in-95 slide-in-from-top-2 z-50 overflow-hidden">
                    <div className="p-4 border-b border-border/50 bg-muted/30">
                        <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider mb-1">{t('dashboard.header.signedInAs')}</p>
                        <p className="text-sm font-medium truncate text-foreground">{session.user?.email}</p>
                    </div>
                    <div className="p-1.5 space-y-1">
                        {/* Mobile-only settings visible in dropdown */}
                        <div className="sm:hidden space-y-1 pb-1 mb-1 border-b border-border/50">
                             <div className="px-2 py-1.5 flex justify-between items-center">
                                <span className="text-sm text-muted-foreground">Theme</span>
                                <ThemeToggle />
                             </div>
                             <div className="px-2 py-1.5 flex justify-between items-center">
                                <span className="text-sm text-muted-foreground">Language</span>
                                <LanguageSwitcher />
                             </div>
                        </div>

                        <button onClick={handleSignOut} className="w-full text-start flex items-center gap-2 px-3 py-2.5 text-sm font-medium text-destructive hover:bg-destructive/10 rounded-lg transition-colors group">
                            <LogoutIcon className="h-4 w-4 transition-transform group-hover:-translate-x-0.5" />
                            {t('dashboard.header.signOut')}
                        </button>
                    </div>
                </div>
            )}
        </div>
      </div>
    </header>
  );
};

