                    dataPacketPosition === 'brain-to-crm' && "left-[50%] translate-x-[150px] opacity-100",   // Brain -> CRM
                    dataPacketPosition === 'brain-to-phone' && "left-[50%] -translate-x-[250px] opacity-100"  // Brain -> Phone
                )} />


                {/* --- LEFT: CUSTOMER PHONE --- */}
                <div className={cn("relative transition-all duration-500 flex justify-center", currentStepIndex === 1 || currentStepIndex === 4 ? "scale-105 opacity-100" : "opacity-60 scale-95 grayscale-[0.3]")}>
