const BuildingIcon = ({ className }: { className?: string }) => <svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="currentColor" className={className}><path fillRule="evenodd" d="M3 2.25a.75.75 0 0 1 .75.75v.54l1.838-.46a9.75 9.75 0 0 1 6.725.738l.108.054a8.25 8.25 0 0 0 5.58.652l3.109-.732a.75.75 0 0 1 .917.81 47.784 47.784 0 0 0 .005 10.337.75.75 0 0 1-.574.812l-3.114.733a9.75 9.75 0 0 1-6.594-.77l-.108-.054a8.25 8.25 0 0 0-5.69-.625l-2.202.55V21a.75.75 0 0 1-1.5 0V3A.75.75 0 0 1 3 2.25Z" clipRule="evenodd" /></svg>;

// --- Constants ---
const steps = [
    { id: 'start', text: 'Waiting for customer...' },
    { id: 'user_msg', text: '1. Customer asks a question' },
    { id: 'ai_process', text: '2. AI extracts intent & details' },
    { id: 'crm_update', text: '3. AI updates Business CRM' },
    { id: 'ai_reply', text: '4. AI replies instantly' },
];

export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [currentStepIndex, setCurrentStepIndex] = useState(0);

    // State for specific animations
    const [messages, setMessages] = useState<any[]>([]);
    const [extractedData, setExtractedData] = useState<{label: string, value: string}[]>([]);
    const [crmCardVisible, setCrmCardVisible] = useState(false);
    const [crmCardStage, setCrmCardStage] = useState('New Lead');
    const [dataPacketPosition, setDataPacketPosition] = useState<'none' | 'phone-to-brain' | 'brain-to-crm' | 'brain-to-phone'>('none');

    useEffect(() => {
        let timeout: ReturnType<typeof setTimeout>;

        const runScenario = () => {
            // Reset for loop
            if (currentStepIndex === 0) {
                setMessages([]);
                setExtractedData([]);
                setCrmCardVisible(false);
                setCrmCardStage('New Lead');
                setDataPacketPosition('none');

                // Start sequence after brief pause
                timeout = setTimeout(() => setCurrentStepIndex(1), 1000);
            }

            // Step 1: User Message
            if (currentStepIndex === 1) {
                timeout = setTimeout(() => {
                    setMessages([{ sender: 'user', text: "Hi! I'm looking for a 3-bedroom villa in The Pearl. Budget is 15k." }]);
                    setDataPacketPosition('phone-to-brain');
                    timeout = setTimeout(() => setCurrentStepIndex(2), 1500);
                }, 500);
            }

            // Step 2: AI Processing (The Brain)
            if (currentStepIndex === 2) {
                setDataPacketPosition('none'); // Packet arrived
                timeout = setTimeout(() => {
                    setExtractedData([
                        { label: 'Intent', value: 'Rent' },
                        { label: 'Type', value: 'Villa' },
                        { label: 'Location', value: 'The Pearl' },
                        { label: 'Budget', value: '15,000' }
                    ]);
                    timeout = setTimeout(() => {
                        setDataPacketPosition('brain-to-crm');
                        setCurrentStepIndex(3);
                    }, 1500);
                }, 500);
            }

            // Step 3: CRM Update
            if (currentStepIndex === 3) {
                timeout = setTimeout(() => {
                    setExtractedData([]); // Clear brain data
                    setDataPacketPosition('none'); // Packet arrived
                    setCrmCardVisible(true);
                    timeout = setTimeout(() => {
                        setCrmCardStage('Qualified'); // Move card
                        timeout = setTimeout(() => {
                            setDataPacketPosition('brain-to-phone'); // Reply signal
                            setCurrentStepIndex(4);
                        }, 1000);
                    }, 1000);
                }, 800);
            }

            // Step 4: AI Reply
            if (currentStepIndex === 4) {
                timeout = setTimeout(() => {
                    setDataPacketPosition('none');
                    setMessages(prev => [...prev, { 
                        sender: 'ai', 
                        text: "I have 3 villas in The Pearl matching your 15k budget. Would you like to see photos?" 
                    }]);

                    // Loop
                    timeout = setTimeout(() => setCurrentStepIndex(0), 5000);
                }, 800);
            }
        };

        runScenario();
        return () => clearTimeout(timeout);
    }, [currentStepIndex]);

    return (
        <div className="w-full max-w-6xl mx-auto flex flex-col gap-12 select-none py-8">

            {/* 1. Status Pill */}
            <div className="flex justify-center">
                <div className="bg-zinc-900/90 dark:bg-white/10 backdrop-blur-md border border-white/10 rounded-full px-6 py-2 shadow-2xl flex items-center gap-3 transition-all duration-300">
                    <span className="relative flex h-3 w-3">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-green-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-3 w-3 bg-green-500"></span>
                    </span>
                    <span className="text-sm font-medium text-white tracking-wide">
                        {steps[currentStepIndex].text}
                    </span>
                </div>
            </div>

            {/* 2. Main Stage */}
            <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 relative px-4">

                {/* Visual Connection Paths (Desktop) */}
                <div className="hidden lg:block absolute top-[180px] left-[20%] right-[20%] h-[2px] bg-gradient-to-r from-transparent via-zinc-300 dark:via-zinc-700 to-transparent -z-10" />

                {/* Animated Data Packet */}
                <div className={cn(
                    "hidden lg:block absolute top-[174px] w-3 h-3 bg-primary rounded-full shadow-[0_0_15px_currentColor] z-0 transition-all duration-[1000ms] ease-in-out",
                    dataPacketPosition === 'none' && "opacity-0",
                    dataPacketPosition === 'phone-to-brain' && "left-[25%] translate-x-0 opacity-100", // Phone -> Brain
                    dataPacketPosition === 'brain-to-crm' && "left-[50%] translate-x-[150px] opacity-100",   // Brain -> CRM
                    dataPacketPosition === 'brain-to-phone' && "left-[50%] -translate-x-[250px] opacity-100"  // Brain -> Phone
                )} />


                {/* --- LEFT: CUSTOMER PHONE --- */}
                <div className={cn("relative transition-all duration-500 flex justify-center", currentStepIndex === 1 || currentStepIndex === 4 ? "scale-105 opacity-100" : "opacity-60 scale-95 grayscale-[0.3]")}>
                    <div className="w-[280px] h-[520px] bg-black rounded-[45px] border-[8px] border-zinc-800 shadow-2xl overflow-hidden relative ring-1 ring-white/20">
                        {/* Dynamic Island */}
                        <div className="absolute top-2 left-1/2 -translate-x-1/2 w-24 h-7 bg-black rounded-full z-20 flex items-center justify-center gap-2 px-2">
                            <div className="w-1.5 h-1.5 rounded-full bg-zinc-800/50" />
                            <div className="w-1.5 h-1.5 rounded-full bg-zinc-800/50" />
                        </div>

                        {/* Screen Content */}
                        <div className="w-full h-full bg-[#EFE7DE] dark:bg-[#0b141a] flex flex-col pt-12 pb-4">
                            {/* WhatsApp Header */}
                            <div className="px-4 py-2 bg-[#F0F2F5] dark:bg-[#202c33] flex items-center gap-3 border-b border-black/5">
                                <Avatar name="Business" className="w-8 h-8 ring-1 ring-black/5" />
                                <div>
                                    <p className="text-xs font-bold text-black dark:text-white">Lusail Real Estate</p>
                                    <p className="text-[9px] text-green-600 dark:text-green-400 font-medium">Business Account</p>
                                </div>
                            </div>

                            {/* Chat Area */}
                            <div className="flex-1 p-3 space-y-3 overflow-y-auto">
                                {messages.map((msg, i) => (
                                    <div key={i} className={cn("flex w-full animate-in slide-in-from-bottom-4 fade-in duration-300", msg.sender === 'user' ? "justify-end" : "justify-start")}>
                                        <div className={cn(
                                            "max-w-[85%] p-2 rounded-lg text-xs leading-relaxed shadow-sm",
                                            msg.sender === 'user' ? "bg-[#dcf8c6] dark:bg-[#005c4b] text-black dark:text-white rounded-tr-none" : "bg-white dark:bg-[#202c33] text-black dark:text-white rounded-tl-none"
                                        )}>
                                            {msg.text}
                                            <span className="block text-[8px] text-right opacity-60 mt-1">10:42 AM</span>
                                        </div>
                                    </div>
                                ))}
                                {currentStepIndex === 4 && messages.length === 1 && (
