import { useToast } from '../../contexts/ToastContext';
import { useTranslation } from '../../contexts/LanguageContext';
import { Icons } from '../ui/Icons';

// --- Password Strength Utilities ---

const calculatePasswordStrength = (password: string): { score: number; label: string } => {
  if (password.length === 0) {
    return { score: 0, label: '' };
  }

  if (password.length < 8) {
    return { score: 1, label: 'Too short' };
  }

  let checks = 0;
  if (/[a-z]/.test(password)) checks++;
  if (/[A-Z]/.test(password)) checks++;
  if (/\d/.test(password)) checks++;
  if (/[^A-Za-z0-9]/.test(password)) checks++;

  switch (checks) {
    case 1:
      return { score: 1, label: 'Weak' };
    case 2:
      return { score: 2, label: 'Medium' };
    case 3:
      return { score: 3, label: 'Strong' };
    case 4:
      return { score: 4, label: 'Very Strong' };
    default:
      return { score: 1, label: 'Weak' };
  }
};

const PasswordStrengthMeter: React.FC<{ score: number; label: string }> = ({ score, label }) => {
  const strengthConfig = {
    1: { color: 'bg-status-red', textColor: 'text-status-red' },
    2: { color: 'bg-status-yellow', textColor: 'text-status-yellow' },
    3: { color: 'bg-status-green', textColor: 'text-status-green' },
    4: { color: 'bg-status-green', textColor: 'text-status-green' },
  };

  const currentConfig = strengthConfig[score as keyof typeof strengthConfig] || { color: 'bg-brand-border', textColor: 'text-brand-text-secondary'};

  return (
    <div className="mt-2 space-y-1.5">
      <div className="flex gap-1.5 h-1.5 rounded-full">
        {[...Array(4)].map((_, i) => (
          <div
            key={i}
            className={`flex-1 rounded-full transition-colors ${
              i < score ? currentConfig.color : 'bg-brand-border'
            }`}
          ></div>
        ))}
      </div>
      {label && <p className={`text-xs font-medium ${currentConfig.textColor}`}>{label}</p>}
    </div>
  );
};


interface AuthPageContentProps {
    onHomeNavigate: () => void;
}

const AuthPageContent: React.FC<AuthPageContentProps> = ({ onHomeNavigate }) => {
    const [view, setView] = useState<'signIn' | 'signUp' | 'forgotPassword'>('signIn');
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [loading, setLoading] = useState(false);
    const [error, setError] = useState<string | null>(null);
    const { addToast } = useToast();
    const { t } = useTranslation();
    const [strength, setStrength] = useState<{ score: number; label: string }>({ score: 0, label: '' });

    const handleAuth = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);

        try {
            if (view === 'signUp') {
                if (strength.score < 3) { throw new Error(t('auth.errors.weakPassword')); }
                const { error: signUpError } = await supabase.auth.signUp({ email, password });
                if (signUpError) throw signUpError;
                addToast(t('auth.verifyEmailToast'), { type: 'success' });
            } else { // 'signIn'
                const { error: signInError } = await supabase.auth.signInWithPassword({ email, password });
                if (signInError) throw signInError;
                addToast(t('auth.signInSuccessToast'), { type: 'success' });
            }
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    const handlePasswordReset = async (e: React.FormEvent) => {
        e.preventDefault();
        setLoading(true);
        setError(null);
        try {
            const { error } = await supabase.auth.resetPasswordForEmail(email, {
                redirectTo: window.location.origin, // Redirect back to the app root
            });
            if (error) throw error;
            addToast('Password reset instructions sent! Please check your email.', { type: 'success' });
            setView('signIn'); // Go back to sign in view
        } catch (err: any) {
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="min-h-screen bg-background flex flex-col justify-center items-center p-4">
            <div className="w-full max-w-sm">
                <button onClick={onHomeNavigate} className="flex items-center justify-center text-center mb-8 group mx-auto gap-2">
                    <Icons.Icon id="logo" className="w-8 h-8 text-primary" />
                    <h1 className="text-2xl font-bold text-foreground tracking-tight group-hover:text-primary transition-colors">Nexus</h1>
                </button>
                <div className="bg-card p-8 rounded-xl shadow-xl border border-border">
                    {view === 'forgotPassword' ? (
                        <>
                            <h2 className="text-xl font-semibold text-foreground text-center mb-6">Reset Security Key</h2>
                            {error && <div className="bg-destructive/10 border border-destructive/20 text-destructive text-sm rounded-md p-3 mb-4">{error}</div>}
                            <form onSubmit={handlePasswordReset} className="space-y-5">
                                <div>
                                    <label htmlFor="email" className="text-sm font-medium text-foreground">{t('auth.emailLabel')}</label>
                                    <Input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder={t('auth.emailPlaceholder')} required className="mt-1.5"/>
                                </div>
                                <Button type="submit" className="w-full" disabled={loading} size="lg">
                                    {loading ? 'Transmitting...' : 'Send Reset Link'}
                                </Button>
                            </form>
                             <p className="text-center text-sm text-muted-foreground mt-6">
                                Return to access?
                                <button onClick={() => { setView('signIn'); setError(null); }} className="font-semibold text-primary hover:underline ms-1">
                                    Authenticate
                                </button>
                            </p>
                        </>
                    ) : (
                        <>
                            <h2 className="text-xl font-semibold text-foreground text-center mb-6">
                                {view === 'signUp' ? t('auth.createTitle') : t('auth.welcomeTitle')}
                            </h2>
                            {error && <div className="bg-destructive/10 border border-destructive/20 text-destructive text-sm rounded-md p-3 mb-4">{error}</div>}
                            <form onSubmit={handleAuth} className="space-y-5">
                                <div>
                                    <label htmlFor="email" className="text-sm font-medium text-foreground">{t('auth.emailLabel')}</label>
                                    <Input id="email" type="email" value={email} onChange={(e) => setEmail(e.target.value)} placeholder={t('auth.emailPlaceholder')} required className="mt-1.5"/>
                                </div>
                                <div>
                                    <div className="flex justify-between items-baseline">
                                        <label htmlFor="password" className="text-sm font-medium text-foreground">{t('auth.passwordLabel')}</label>
                                        {view === 'signIn' && (
                                            <button type="button" onClick={() => { setView('forgotPassword'); setError(null); }} className="text-xs font-semibold text-primary hover:underline">
                                                Recovery?
                                            </button>
                                        )}
                                    </div>
                                    <Input id="password" type="password" value={password} onChange={(e) => { setPassword(e.target.value); if (view === 'signUp') { setStrength(calculatePasswordStrength(e.target.value)); }}} placeholder={t('auth.passwordPlaceholder')} required className="mt-1.5"/>
                                    {view === 'signUp' && password.length > 0 && (<PasswordStrengthMeter score={strength.score} label={strength.label} />)}
                                </div>
                                <Button type="submit" className="w-full" disabled={loading} size="lg">
                                    {loading ? (view === 'signUp' ? t('auth.signingUpButton') : t('auth.signingInButton')) : (view === 'signUp' ? t('auth.signUpButton') : t('auth.signInButton'))}
                                </Button>
                            </form>
                            <p className="text-center text-sm text-muted-foreground mt-6">
                                {view === 'signUp' ? t('auth.promptSignIn') : t('auth.promptSignUp')}
                                <button onClick={() => { setView(view === 'signUp' ? 'signIn' : 'signUp'); setError(null); }} className="font-semibold text-primary hover:underline ms-1">
                                    {view === 'signUp' ? t('auth.signInButton') : t('auth.signUpButton')}
                                </button>
                            </p>
                        </>
                    )}
                </div>
            </div>
        </div>
    );
}

