export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [step, setStep] = useState<DemoStep>('start');
    const [kanbanCardStage, setKanbanCardStage] = useState('New');
    const [showTag, setShowTag] = useState(false);

    // Channel state: switches between WhatsApp and Instagram visualizations
    const [channel, setChannel] = useState<'whatsapp' | 'instagram'>('whatsapp');

    const [isWorkflowVisible, setIsWorkflowVisible] = useState(false);
    const [activeNode, setActiveNode] = useState<string|null>(null);

    const stepIndexRef = useRef(0);

    useEffect(() => {
        const runSequence = () => {
            const current = demoSequence[stepIndexRef.current];
            setStep(current.step);
            setActiveNode(null);

            // Specific actions for steps
            if (current.step === 'showWorkflow') setIsWorkflowVisible(true);
            if (current.step === 'triggerActive') setActiveNode('trigger');
            if (current.step === 'action1Active') setActiveNode('action1');
            if (current.step === 'action2Active') { setActiveNode('action2'); setShowTag(true); }
            if (current.step === 'action3Active') { setActiveNode('action3'); setTimeout(() => setKanbanCardStage('Contacted'), 500); }
            if (current.step === 'action4Active') setActiveNode('action4');

            stepIndexRef.current = (stepIndexRef.current + 1) % demoSequence.length;

            if (stepIndexRef.current === 0) {
                setTimeout(() => {
                   setIsWorkflowVisible(false);
                   setKanbanCardStage('New');
                   setShowTag(false);
                   // Toggle channel for the next loop
                   setChannel(prev => prev === 'whatsapp' ? 'instagram' : 'whatsapp');
                }, 1000);
            }

            setTimeout(runSequence, current.duration);
        };
        const timeoutId = setTimeout(runSequence, 500);
        return () => clearTimeout(timeoutId);
    }, []);

    const messages = useMemo(() => {
        const base = [{ sender: 'user', name: 'Nasser Al-Khater', text: t('homepage.demo.chat.u1'), avatar: 'Nasser' }];
        if (stepIndexRef.current > 6) base.push({ sender: 'ai', name: 'Flowtiva AI', text: t('homepage.demo.chat.a1'), avatar: 'Flowtiva' });
        if (stepIndexRef.current > 7) base.push({ sender: 'user', name: 'Nasser Al-Khater', text: t('homepage.demo.chat.u2'), avatar: 'Nasser' });
        if (stepIndexRef.current > 11) base.push({ sender: 'ai', name: 'Flowtiva AI', text: t('homepage.demo.chat.a2'), avatar: 'Flowtiva' });
        if (stepIndexRef.current > 12) base.push({ sender: 'user', name: 'Nasser Al-Khater', text: t('homepage.demo.chat.u3'), avatar: 'Nasser' });
        if (stepIndexRef.current > 15) base.push({ sender: 'ai', name: 'Flowtiva AI', text: t('homepage.demo.chat.a3'), avatar: 'Flowtiva' });
        return base;
    }, [step, t]);

    // Styles vary based on channel
    const getBubbleStyle = (sender: string) => {
        if (channel === 'whatsapp') {
            return sender === 'user' 
                ? 'bg-brand-secondary rounded-bl-none text-brand-text-primary' 
                : 'bg-[#DCF8C6] dark:bg-[#005c4b] text-brand-text-primary rounded-br-none';
        } else {
            // Instagram
            return sender === 'user' 
                ? 'bg-gray-100 dark:bg-gray-800 rounded-bl-none text-brand-text-primary' 
                : 'bg-gradient-to-r from-purple-500 to-pink-500 text-white rounded-br-none';
        }
    };

    return (
        <div className="h-[640px] md:h-auto md:aspect-video bg-brand-secondary rounded-lg flex flex-col md:flex-row overflow-hidden p-3 gap-3">
            {/* Chat Panel */}
            <div className="relative flex-1 flex flex-col bg-brand-primary rounded-md border border-brand-border overflow-hidden transition-colors duration-500">
                {/* Header */}
                <div className="p-2 border-b border-brand-border flex items-center gap-2 transition-colors duration-500">
                    <Avatar name="Nasser Al-Khater" className="w-8 h-8" />
                    <div className="flex-1">
                        <p className="text-sm font-semibold text-left text-brand-text-primary">Nasser Al-Khater</p>
                        <p className="text-[10px] text-left text-brand-text-secondary flex items-center gap-1">
                            {channel === 'whatsapp' ? <WhatsAppIcon /> : <InstagramIcon />}
                            {channel === 'whatsapp' ? '+974 5512 3456' : '@nasser_ak'}
                        </p>
                    </div>
                </div>

                {/* Message List */}
                <div className="flex-1 p-3 space-y-3 overflow-y-auto text-sm">
                    {messages.map((msg, i) => (
                        <div key={i} className={`demo-bubble flex items-end gap-2 ${msg.sender === 'user' ? 'justify-start' : 'justify-end'}`}>
                            {msg.sender === 'user' && <Avatar name={msg.avatar} className="w-6 h-6" />}
                            <div className={`max-w-[70%] p-2 rounded-lg transition-colors duration-500 ${getBubbleStyle(msg.sender)}`}>
                                {msg.text}
                            </div>
                            {msg.sender === 'ai' && <Avatar name={msg.avatar} className="w-6 h-6" />}
                        </div>
                    ))}
                     {(step === 'aiTyping1' || step === 'aiTyping2' || step === 'aiTyping3') && (
                        <div className="demo-bubble flex items-end gap-2 justify-end">
                            <div className={`p-2 rounded-lg rounded-br-none flex items-center gap-1 transition-colors duration-500 ${channel === 'whatsapp' ? 'bg-[#DCF8C6] dark:bg-[#005c4b]' : 'bg-gradient-to-r from-purple-500 to-pink-500'}`}>
                                <span className="demo-typing-dot w-1.5 h-1.5 bg-current opacity-70 rounded-full" />
                                <span className="demo-typing-dot w-1.5 h-1.5 bg-current opacity-70 rounded-full" style={{ animationDelay: '0.2s' }} />
                                <span className="demo-typing-dot w-1.5 h-1.5 bg-current opacity-70 rounded-full" style={{ animationDelay: '0.4s' }} />
                            </div>
                           <Avatar name="Flowtiva" className="w-6 h-6" />
                        </div>
                    )}
                </div>
                <div className="p-2 border-t border-brand-border">
                    {step === 'humanTakeover'
                        ? <div className="relative w-full h-9 bg-brand-secondary rounded-md border border-brand-accent ring-2 ring-brand-accent/50 flex items-center px-2 text-sm text-brand-text-primary">
                            {t('homepage.demo.chat.typeReply')}<span className="w-0.5 h-4 bg-brand-accent animate-ping ml-1"></span>
                          </div>
                        : <div className="w-full h-9 bg-brand-secondary rounded-md border border-brand-border flex items-center justify-center text-xs text-brand-text-secondary">{t('homepage.demo.chat.agentActive')}</div>
                    }
                </div>
                {step === 'aiReply1' && <Tooltip className="bottom-14 left-4">{t('homepage.demo.workflow.tooltip2')}</Tooltip>}
                {step === 'humanTakeover' && <Tooltip className="bottom-14 left-4">{t('homepage.demo.workflow.tooltip4')}</Tooltip>}
            </div>

            {/* Workflow & CRM Panels */}
            <div className="flex-1 md:flex-none w-full md:w-2/5 flex flex-col gap-3">
                <div className="flex-1">
                     <WorkflowPanel isVisible={isWorkflowVisible} activeNode={activeNode} />
                     {step === 'showWorkflow' && <Tooltip className="top-2 left-4">{t('homepage.demo.workflow.tooltip1')}</Tooltip>}
                </div>
                <div className="flex-1 flex flex-col bg-brand-primary rounded-md border border-brand-border p-2 gap-2">
                     <div className="flex-1 flex gap-2 overflow-hidden">
                        <div className="flex-1">
                            <h3 className="text-xs font-bold uppercase text-brand-text-secondary p-1">New</h3>
                            {kanbanCardStage === 'New' && <div className="relative p-2 bg-brand-secondary rounded-md border border-blue-500/50 transition-all duration-500">
                                <p className="text-xs font-bold">Nasser Al-Khater</p>
                                <p className="text-xs text-brand-text-secondary mt-1">"{t('homepage.demo.chat.u1').substring(0, 20)}..."</p>
                            </div>}
                        </div>
                        <div className="flex-1">
                             <h3 className="text-xs font-bold uppercase text-brand-text-secondary p-1">Contacted</h3>
                             {kanbanCardStage === 'Contacted' && <div className="relative p-2 bg-brand-secondary rounded-md border border-purple-500/50 transition-all duration-500">
                                <p className="text-xs font-bold">Nasser Al-Khater</p>
                                <p className="text-xs text-brand-text-secondary mt-1">"{t('homepage.demo.chat.u1').substring(0, 20)}..."</p>
                                {showTag && <div className="mt-1"><span className="text-[10px] font-semibold bg-brand-accent/20 text-brand-accent px-1.5 py-0.5 rounded-full">buying</span></div>}
                            </div>}
                        </div>
                    </div>
                    {step === 'action3Active' && <Tooltip className="bottom-2 left-4">{t('homepage.demo.workflow.tooltip3')}</Tooltip>}
                </div>
            </div>
        </div>
    );
};

