  async getWorkflows(): Promise<Workflow[]> {
    const { data: workflowsData, error: workflowsError } = await supabaseClient
      .from('workflows')
      .select(`
        id,
        tenant_id,
        name,
        trigger_type,
        trigger_config,
        is_active,
        created_at,
        workflow_actions (
          id,
          step_order,
          action_type,
          action_config
        )
      `)
      .order('created_at', { ascending: false });

    if (workflowsError) {
      console.error("Error fetching workflows:", workflowsError.message);
      throw new Error(workflowsError.message);
    }

    return (workflowsData || []).map((wf: any) => ({
      id: wf.id,
      tenant_id: wf.tenant_id,
      name: wf.name,
      trigger: {
        type: wf.trigger_type,
        config: wf.trigger_config || {},
      },
      actions: (wf.workflow_actions || []).sort((a: any, b: any) => a.step_order - b.step_order).map((act: any) => ({
        id: act.id,
        type: act.action_type,
        config: act.action_config || {},
      })),
      is_active: wf.is_active,
      created_at: wf.created_at,
    }));
  },

  async createWorkflow(workflow: Omit<Workflow, 'id' | 'tenant_id' | 'created_at'>): Promise<Workflow> {
    const { data: newWorkflow, error: workflowError } = await supabaseClient
      .from('workflows')
      .insert({
        name: workflow.name,
        trigger_type: workflow.trigger.type,
        trigger_config: workflow.trigger.config,
        is_active: workflow.is_active,
      })
      .select()
      .single();

    if (workflowError) throw new Error(workflowError.message);
    if (!newWorkflow) throw new Error("Failed to create workflow.");

    const actionsToInsert = workflow.actions.map((action, index) => ({
      workflow_id: newWorkflow.id,
      step_order: index,
      action_type: action.type,
      action_config: action.config,
    }));

    if (actionsToInsert.length > 0) {
      const { error: actionsError } = await supabaseClient
        .from('workflow_actions')
        .insert(actionsToInsert);
      if (actionsError) {
        await supabaseClient.from('workflows').delete().eq('id', newWorkflow.id);
        throw new Error(actionsError.message);
      }
    }

    const { data: fullWorkflowData, error: fetchError } = await supabaseClient.from('workflows').select(`*, workflow_actions(*)`).eq('id', newWorkflow.id).single();
    if(fetchError) throw fetchError;

    const wf = fullWorkflowData;
    return {
      id: wf.id, tenant_id: wf.tenant_id, name: wf.name,
      trigger: { type: wf.trigger_type, config: wf.trigger_config || {} },
      actions: (wf.workflow_actions || []).sort((a: any, b: any) => a.step_order - b.step_order).map((act: any) => ({ id: act.id, type: act.action_type, config: act.action_config || {} })),
      is_active: wf.is_active, created_at: wf.created_at,
    };
  },

  async updateWorkflow(workflow: Partial<Workflow> & { id: string }): Promise<Workflow> {
    const { id, name, trigger, actions, is_active } = workflow;

    const updatePayload: any = { name, is_active, updated_at: 'now()' };
    if (trigger) {
      updatePayload.trigger_type = trigger.type;
      updatePayload.trigger_config = trigger.config;
    }

    const { error: workflowError } = await supabaseClient
      .from('workflows')
      .update(updatePayload)
      .eq('id', id);
    if (workflowError) throw new Error(workflowError.message);

    if (actions) {
        const { error: deleteError } = await supabaseClient.from('workflow_actions').delete().eq('workflow_id', id);
        if (deleteError) throw new Error(deleteError.message);

        const actionsToInsert = actions.map((action, index) => ({ workflow_id: id, step_order: index, action_type: action.type, action_config: action.config }));
        if (actionsToInsert.length > 0) {
            const { error: insertError } = await supabaseClient.from('workflow_actions').insert(actionsToInsert);
            if (insertError) throw new Error(insertError.message);
        }
    }

    const { data: fullWorkflowData, error: fetchError } = await supabaseClient.from('workflows').select(`*, workflow_actions(*)`).eq('id', id).single();
    if(fetchError) throw fetchError;
    const wf = fullWorkflowData;
    return {
      id: wf.id, tenant_id: wf.tenant_id, name: wf.name,
      trigger: { type: wf.trigger_type, config: wf.trigger_config || {} },
      actions: (wf.workflow_actions || []).sort((a: any, b: any) => a.step_order - b.step_order).map((act: any) => ({ id: act.id, type: act.action_type, config: act.action_config || {} })),
      is_active: wf.is_active, created_at: wf.created_at,
    };
  },

  async updateWorkflowStatus(workflowId: string, isActive: boolean): Promise<void> {
    const { error } = await supabaseClient
      .from('workflows')
      .update({ is_active: isActive, updated_at: 'now()' })
      .eq('id', workflowId);
    if (error) throw new Error(error.message);
  },

  async deleteWorkflow(workflowId: string): Promise<void> {
    const { error } = await supabaseClient
      .from('workflows')
      .delete()
      .eq('id', workflowId);
    if (error) throw new Error(error.message);
  },

  async getWorkflowHistory(page: number, pageSize: number): Promise<WorkflowHistory[]> {
    const from = (page - 1) * pageSize;
    const to = from + pageSize - 1;

    const { data, error } = await supabaseClient
      .from('workflow_history')
      .select(`
        id,
        workflow_id,
        triggered_at,
        trigger_event,
        status,
        actions_log,
        error_message,
        workflows ( name )
      `)
      .order('triggered_at', { ascending: false })
      .range(from, to);

    if (error) {
      console.error("Error fetching workflow history:", error.message);
      throw new Error(error.message);
    }

    return (data || []).map((h: any) => ({
      ...h,
      workflow_name: h.workflows.name,
      workflows: undefined, // remove nested object
    }));
  },

  // --- BILLING & SEARCH FUNCTIONS ---
  async getBillingDashboardData(): Promise<BillingDashboardData | null> {
    const { data, error } = await supabaseClient.rpc('get_billing_dashboard_data').single();
    if (error) {
        console.error("Error fetching billing dashboard data:", error.message);
        throw new Error(error.message);
    }
    if (data && Object.keys(data).length > 0) {
        return data as BillingDashboardData;
    }
    return null;
  },

  async getPlans(): Promise<Plan[]> {
    const { data, error } = await supabaseClient.from('plans').select('*').order('price_monthly');
    if (error) {
        console.error("Error fetching plans:", error.message);
        throw new Error(error.message);
    }
    return data || [];
  },

  async changeSubscriptionPlan(planId: string, billingCycle: 'monthly' | 'yearly'): Promise<void> {
    const { error } = await supabaseClient.rpc('change_subscription_plan', {
        p_new_plan_id: planId,
        p_new_billing_cycle: billingCycle,
    });
    if (error) {
        console.error("Error changing subscription plan:", error.message);
        throw new Error(error.message);
    }
  },

  async updatePaymentMethod(cardType: string, last4: string, expiry: string): Promise<void> {
    const { error } = await supabaseClient.rpc('update_payment_method', {
        p_card_type: cardType,
        p_last4: last4,
        p_expiry: expiry,
    });
    if (error) {
        console.error("Error updating payment method:", error.message);
        throw new Error(error.message);
    }
  },

  async getInvoiceDetails(invoiceId: string): Promise<InvoiceDetails | null> {
    const { data, error } = await supabaseClient.rpc('get_invoice_details', { p_invoice_id: invoiceId }).single();
    if (error) {
        console.error("Error fetching invoice details:", error.message);
        throw new Error(error.message);
    }
    if (data && Object.keys(data).length > 0) {
        return data as InvoiceDetails;
    }
    return null;
  },

  async searchGlobally(query: string): Promise<any[]> {
    if (!query) return [];
    const { data, error } = await supabaseClient.rpc('search_globally', { p_query: query });
    if (error) {
      console.error("Error performing global search:", error.message);
      throw new Error(error.message);
    }
    return data || [];
  },

  // --- AI TELEMETRY & GOVERNANCE FUNCTIONS ---
  async getAITelemetryStats(): Promise<AITelemetryStats> {
    // This assumes an RPC 'get_ai_telemetry_stats' exists.
    const { data, error } = await this.client.rpc('get_ai_telemetry_stats').single();
    if (error) {
        console.error("Error fetching AI telemetry stats:", error.message);
        throw new Error(error.message);
    }
    return (data as AITelemetryStats) || { total_calls: 0, cache_hit_rate: 0, error_rate: 0, avg_latency: 0, calls_by_action: [] };
  },

  async logAIAlert(alert: { type: AIAlert['alert_type']; message: string; metadata?: object }): Promise<void> {
    const { error } = await this.client.rpc('log_ai_alert', { 
        p_type: alert.type,
        p_message: alert.message,
        p_metadata: alert.metadata
    });
    if (error) {
        console.error("Error logging AI alert:", error.message);
    }
  },

  async getAIReports(): Promise<AIReport[]> {
    const { data, error } = await this.client.from('ai_reports').select('*').order('created_at', { ascending: false });
    if (error) {
        console.error("Error fetching AI reports:", error.message);
        throw error;
    }
    return data || [];
  },

  async getAIAlerts(): Promise<AIAlert[]> {
    const { data, error } = await this.client.from('ai_alerts').select('*').order('created_at', { ascending: false }).limit(5);
    if (error) {
      console.error("Error fetching AI alerts:", error.message);
      throw error;
    }
    return data || [];
  },

  // --- SUPERADMIN FUNCTIONS ---
  async getSystemStats(): Promise<SystemStats> {
    const { data, error } = await supabaseClient.rpc('get_system_stats').single();
    if (error) throw new Error(error.message);
    if (data && Object.keys(data).length > 0) {
      return data as SystemStats;
    }
    return { total_users: 0, total_instances: 0, active_instances: 0, messages_last_24h: 0 };
  },

  async getSuperadminDashboardData(): Promise<SuperadminDashboardData> {
    const { data, error } = await supabaseClient.rpc('get_superadmin_dashboard_data').single();
    if (error) {
        console.error("Error fetching superadmin dashboard data:", error);
        throw new Error(error.message);
    }
    return data as SuperadminDashboardData;
  },

  async getAllUsers(): Promise<PlatformUser[]> {
    const { data, error } = await supabaseClient.rpc('get_all_users');
    if (error) throw new Error(error.message);
    return data;
  },

  async getAllInstances(): Promise<AllInstances[]> {
    const { data, error } = await supabaseClient.rpc('get_all_instances');
    if (error) throw new Error(error.message);
    return data;
  },

  async forceStopInstance(instanceId: string): Promise<void> {
    const { error } = await supabaseClient.rpc('force_stop_instance', { p_instance_id: instanceId });
    if (error) throw new Error(error.message);
  },

  async getSystemLogs(limit: number = 100): Promise<SystemLog[]> {
    const { data, error } = await supabaseClient.rpc('get_system_logs', { p_limit: limit });
    if (error) throw new Error(error.message);
    return data || [];
  },
};

