        pending: { dot: 'bg-gray-400', text: 'text-gray-400' },
        linking: { dot: 'bg-blue-400 animate-pulse', text: 'text-blue-400' },
        running: { dot: 'bg-status-green', text: 'text-status-green' },
        inactive: { dot: 'bg-gray-400', text: 'text-gray-400' },
        failed: { dot: 'bg-status-red', text: 'text-status-red' },
