                                            <Button size="sm" variant="ghost" className="text-status-red hover:bg-status-red/10" onClick={() => setInstanceForDelete(instance)}>{t('common.delete')}</Button>
                                        </div>
                                    </div>
                                </CardContent>
                            </Card>
                        ))}
