import React, { useState } from 'react';
import { supabase } from '../../services/supabaseService';
import { InstagramInstance } from '../../types';
import { Modal, ModalContent, ModalHeader, ModalTitle, ModalDescription, ModalFooter } from '../ui/Modal';
import { Button } from '../ui/Button';
import { Input } from '../ui/Input';
import { useToast } from '../../contexts/ToastContext';

interface CreateReposterModalProps {
    isOpen: boolean;
    onClose: () => void;
    onJobCreated: () => void;
    instances: InstagramInstance[];
}

export const CreateReposterModal: React.FC<CreateReposterModalProps> = ({ isOpen, onClose, onJobCreated, instances }) => {
    const [instanceId, setInstanceId] = useState('');
    const [targetUsername, setTargetUsername] = useState('');
    const [maxReels, setMaxReels] = useState(10);
    const [interval, setInterval] = useState(60);
    const [isLoading, setIsLoading] = useState(false);
    const { addToast } = useToast();

    const handleSubmit = async () => {
        if (!instanceId || !targetUsername) {
            addToast("Please fill in all required fields.", { type: 'error' });
            return;
        }

        setIsLoading(true);
        try {
            await supabase.createInstagramReposterJob({
                instanceId,
                targetUsername: targetUsername.replace('@', '').trim(),
                maxReels,
                interval
            });
            addToast('Reposter job created successfully!', { type: 'success' });
            onJobCreated();
            onClose();
        } catch (error: any) {
            addToast(error.message, { type: 'error' });
        } finally {
            setIsLoading(false);
        }
    };

    return (
        <Modal open={isOpen} onOpenChange={onClose}>
            <ModalContent>
                <ModalHeader>
                    <ModalTitle>New Reels Reposter Job</ModalTitle>
                    <ModalDescription>Automate downloading and reposting reels from another account.</ModalDescription>
                </ModalHeader>
                <div className="p-6 space-y-4">
                    <div>
                        <label className="text-sm font-medium">Source Account (Your Account)</label>
                        <select 
                            value={instanceId} 
                            onChange={(e) => setInstanceId(e.target.value)} 
                            className="mt-1 w-full h-10 rounded-md border border-brand-border bg-brand-primary px-2 text-sm"
                        >
                            <option value="" disabled>Select an account</option>
                            {instances.map(inst => (
                                <option key={inst.id} value={inst.id}>@{inst.username}</option>
                            ))}
                        </select>
                        <p className="text-xs text-brand-text-secondary mt-1">This account will post the reels.</p>
                    </div>

                    <div>
                        <label className="text-sm font-medium">Target Username</label>
                        <Input 
                            value={targetUsername} 
                            onChange={(e) => setTargetUsername(e.target.value)} 
                            placeholder="e.g., excitingcinema" 
                        />
                        <p className="text-xs text-brand-text-secondary mt-1">The account to scrape reels from.</p>
                    </div>

                    <div className="grid grid-cols-2 gap-4">
                        <div>
                            <label className="text-sm font-medium">Max Reels to Fetch</label>
                            <Input 
                                type="number" 
                                min={1} 
                                max={100} 
                                value={maxReels} 
                                onChange={(e) => setMaxReels(parseInt(e.target.value))} 
                            />
                        </div>
                        <div>
                            <label className="text-sm font-medium">Interval (Minutes)</label>
                            <Input 
                                type="number" 
                                min={10} 
                                value={interval} 
                                onChange={(e) => setInterval(parseInt(e.target.value))} 
                            />
                        </div>
                    </div>
                </div>
                <ModalFooter>
                    <Button variant="outline" onClick={onClose} disabled={isLoading}>Cancel</Button>
                    <Button onClick={handleSubmit} disabled={isLoading || !instanceId || !targetUsername}>
                        {isLoading ? 'Creating...' : 'Create Job'}
                    </Button>
                </ModalFooter>
            </ModalContent>
        </Modal>
    );
};

