// --- Demo Types ---
type DemoStep = 'idle' | 'msg_incoming' | 'msg_received' | 'ai_thinking' | 'ai_processing' | 'ai_replying' | 'complete';

interface DemoState {
    step: DemoStep;
    chat: { sender: 'user' | 'ai', text: string }[];
    leadCard: { name: string; intent: string; status: string };
}

export const InteractiveDemo: React.FC = () => {
    const { t } = useTranslation();
    const [state, setState] = useState<DemoState>({
        step: 'idle',
        chat: [],
        leadCard: { name: '', intent: '', status: '' }
    });

    // Reset sequence loop
    useEffect(() => {
        let isMounted = true;

        const runDemo = async () => {
            if (!isMounted) return;

            // 1. Initial State
            setState({ 
                step: 'idle', 
                chat: [], 
                leadCard: { name: '', intent: '', status: '' } 
            });
            await new Promise(r => setTimeout(r, 1000));
            if (!isMounted) return;

            // 2. Incoming Message
            setState(prev => ({ ...prev, step: 'msg_incoming' }));
            await new Promise(r => setTimeout(r, 1500));
            if (!isMounted) return;

            // 3. Message Received
            setState(prev => ({ 
                ...prev, 
                step: 'msg_received',
                chat: [{ sender: 'user', text: "Hi, I'm looking for a 3-bedroom villa in Lusail." }]
            }));
            await new Promise(r => setTimeout(r, 1000));
            if (!isMounted) return;

            // 4. AI Thinking (Brain Pulse)
            setState(prev => ({ ...prev, step: 'ai_thinking' }));
            await new Promise(r => setTimeout(r, 1500));
            if (!isMounted) return;

            // 5. AI Processing (Data Extraction)
            setState(prev => ({ 
                ...prev, 
                step: 'ai_processing',
                leadCard: { name: 'New Customer', intent: 'Buying', status: 'Hot Lead' }
            }));
            await new Promise(r => setTimeout(r, 1500));
            if (!isMounted) return;

            // 6. AI Replying
            setState(prev => ({ 
                ...prev, 
                step: 'ai_replying',
                chat: [
                    ...prev.chat,
                    { sender: 'ai', text: "Welcome! We have a beautiful 3-bedroom villa available in Lusail. Would you like to see photos?" }
                ]
            }));
            await new Promise(r => setTimeout(r, 1500));
            if (!isMounted) return;

            // 7. Complete
            setState(prev => ({ ...prev, step: 'complete' }));
            await new Promise(r => setTimeout(r, 4000));
            if (!isMounted) return;

            // Loop
            runDemo();
        };

        runDemo();
        return () => { isMounted = false; };
    }, []);

    // Dynamic Narrative Text
    const getNarrative = () => {
        switch(state.step) {
            case 'idle': return "Waiting for a customer...";
            case 'msg_incoming': return "1. Customer sends a message on WhatsApp";
            case 'msg_received': return "1. Customer sends a message on WhatsApp";
            case 'ai_thinking': return "2. Flowtiva AI analyzes the intent instantly";
            case 'ai_processing': return "3. It automatically creates a lead in your CRM";
            case 'ai_replying': return "4. And sends a perfect, human-like reply";
            case 'complete': return "Done! The lead is captured and engaged.";
            default: return "";
        }
    };

    return (
        <div className="w-full flex flex-col items-center">

            {/* Narrative Header */}
            <div className="h-16 mb-8 flex items-center justify-center">
                <div className="bg-card/80 backdrop-blur-md border border-border px-6 py-3 rounded-full shadow-sm transition-all duration-500 ease-in-out">
                    <p className="text-lg md:text-xl font-bold text-foreground text-center">
                        {getNarrative()}
                    </p>
                </div>
            </div>

            {/* Stage Container */}
            <div className="relative w-full max-w-4xl flex flex-col md:flex-row items-center justify-center gap-8 md:gap-16">

                {/* DEVICE: PHONE */}
                <div className="relative w-[280px] h-[560px] bg-gray-900 rounded-[40px] border-[8px] border-gray-800 shadow-2xl overflow-hidden flex flex-col z-10 transition-transform duration-500">
                    {/* Notch */}
                    <div className="absolute top-0 left-1/2 -translate-x-1/2 w-32 h-6 bg-gray-800 rounded-b-xl z-20"></div>

                    {/* App Header */}
                    <div className="bg-[#075E54] h-20 pt-6 px-4 flex items-center gap-3 shadow-md z-10">
                        <div className="w-8 h-8 bg-white/20 rounded-full flex items-center justify-center">
                            <Avatar name="Customer" className="w-full h-full"/>
                        </div>
                        <div className="text-white">
                            <p className="text-sm font-bold">New Customer</p>
                            <p className="text-[10px] opacity-80">online</p>
                        </div>
                    </div>

                    {/* Chat Area */}
                    <div className="flex-1 bg-[#ECE5DD] p-4 space-y-4 overflow-y-auto relative">
                        {/* Chat Pattern Overlay */}
                        <div className="absolute inset-0 opacity-[0.05] bg-[url('https://user-images.githubusercontent.com/15075759/28719144-86dc0f70-73b1-11e7-911d-60d70fcded21.png')] pointer-events-none"></div>

                        {state.chat.map((msg, i) => (
                            <div key={i} className={`relative z-10 flex ${msg.sender === 'user' ? 'justify-start' : 'justify-end'} animate-in slide-in-from-bottom-2 fade-in duration-300`}>
                                <div className={`max-w-[85%] p-3 rounded-lg text-sm shadow-sm ${msg.sender === 'user' ? 'bg-white text-gray-800 rounded-bl-none' : 'bg-[#DCF8C6] text-gray-800 rounded-br-none'}`}>
                                    {msg.text}
