                    </div>

                    {/* Floating App Icon */}
                    <div className="absolute bottom-20 right-4 w-10 h-10 bg-white rounded-full shadow-lg flex items-center justify-center z-20">
                         <WhatsAppIcon className="w-6 h-6" />
                    </div>
                </div>

                {/* VISUALIZER: THE CONNECTION */}
                <div className="absolute md:static top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 md:translate-x-0 md:translate-y-0 z-0 flex items-center justify-center w-24 h-24">
                     {/* The "Brain" Pulse */}
                    <div className={`relative flex items-center justify-center transition-all duration-500 ${state.step === 'ai_thinking' || state.step === 'ai_processing' ? 'scale-150 opacity-100' : 'scale-100 opacity-30 grayscale'}`}>
                        <div className="absolute inset-0 bg-primary/20 rounded-full animate-ping"></div>
