                <div className={`w-[300px] bg-card border border-border rounded-xl shadow-2xl overflow-hidden transition-all duration-700 transform ${state.step === 'idle' || state.step === 'msg_incoming' ? 'opacity-50 translate-y-8 blur-sm' : 'opacity-100 translate-y-0 blur-0'}`}>
