                </div>

                {/* VISUALIZER: THE CONNECTION */}
                <div className="absolute md:static top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 md:translate-x-0 md:translate-y-0 z-0 flex items-center justify-center w-32 h-32">
                     {/* The "Brain" Pulse */}
                    <div className={`relative flex items-center justify-center transition-all duration-700 ${state.step === 'ai_thinking' || state.step === 'ai_processing' ? 'scale-125 opacity-100' : 'scale-75 opacity-20 grayscale'}`}>
                        <div className="absolute inset-0 bg-primary/30 rounded-full animate-ping"></div>
                        <div className="absolute inset-0 bg-primary/10 rounded-full animate-pulse delay-75"></div>
                        <div className="w-20 h-20 bg-card rounded-full shadow-[0_0_40px_-10px_rgba(var(--primary),0.5)] border-4 border-primary flex items-center justify-center z-10 relative overflow-hidden">
                             <div className="absolute inset-0 bg-gradient-to-tr from-primary/20 to-transparent"></div>
                             <BrainIcon className="w-10 h-10 text-primary relative z-10" />
                        </div>

                        {/* Connecting Lines (Desktop only) */}
                        <div className={`hidden md:block absolute top-1/2 right-full w-20 h-1 bg-gradient-to-r from-transparent to-primary transition-all duration-500 ${state.step === 'msg_received' || state.step === 'ai_thinking' ? 'opacity-100 width-20' : 'opacity-0 width-0'}`} />
                        <div className={`hidden md:block absolute top-1/2 left-full w-20 h-1 bg-gradient-to-l from-transparent to-primary transition-all duration-500 ${state.step === 'ai_processing' ? 'opacity-100 width-20' : 'opacity-0 width-0'}`} />
                    </div>
                </div>

                {/* DEVICE: CRM CARD */}
                <div className={`w-[320px] bg-card border border-border rounded-2xl shadow-2xl overflow-hidden transition-all duration-700 transform ${state.step === 'idle' || state.step === 'msg_incoming' ? 'opacity-40 translate-y-8 blur-[2px] scale-95' : 'opacity-100 translate-y-0 blur-0 scale-100'}`}>
                    <div className="bg-muted/80 backdrop-blur-sm p-4 border-b border-border flex justify-between items-center">
                        <div className="flex items-center gap-2">
                             <div className="w-3 h-3 rounded-full bg-red-400 shadow-sm"></div>
                             <div className="w-3 h-3 rounded-full bg-yellow-400 shadow-sm"></div>
                             <div className="w-3 h-3 rounded-full bg-green-400 shadow-sm"></div>
                        </div>
                        <span className="text-[10px] font-bold uppercase tracking-widest text-muted-foreground">Flowtiva CRM</span>
                    </div>

                    <div className="p-6 space-y-6 bg-gradient-to-b from-card to-muted/20">
                        {/* Field 1 */}
                        <div className="space-y-2">
                            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wide">Contact Name</label>
                            <div className="h-10 w-full bg-background rounded-lg border border-border flex items-center px-4 shadow-sm relative overflow-hidden group">
                                {state.leadCard.name && (
                                    <span className="text-sm font-semibold text-foreground animate-in slide-in-from-left fade-in duration-500 flex items-center gap-2">
                                        <Avatar name="Nasser" className="w-5 h-5" />
                                        {state.leadCard.name}
                                    </span>
                                )}
                                <div className={`absolute bottom-0 left-0 h-0.5 bg-primary transition-all duration-1000 ${state.leadCard.name ? 'w-full' : 'w-0'}`}></div>
                            </div>
                        </div>

                         {/* Field 2 */}
                         <div className="space-y-2">
                            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wide">Intent Detected</label>
                            <div className="h-10 w-full bg-background rounded-lg border border-border flex items-center px-4 shadow-sm relative overflow-hidden">
                                {state.leadCard.intent && (
                                    <span className="text-sm font-bold text-primary animate-in slide-in-from-left fade-in duration-500 delay-150 bg-primary/10 px-2 py-0.5 rounded-md">
                                        {state.leadCard.intent}
                                    </span>
                                )}
                            </div>
                        </div>

                         {/* Field 3 */}
                         <div className="space-y-2">
                            <label className="text-xs font-bold text-muted-foreground uppercase tracking-wide">Pipeline Stage</label>
                            <div className="h-10 w-full bg-background rounded-lg border border-border flex items-center px-4 shadow-sm relative overflow-hidden">
                                {state.leadCard.status && (
                                    <div className="flex items-center gap-2 animate-in slide-in-from-left fade-in duration-500 delay-300">
                                        <span className="w-2.5 h-2.5 rounded-full bg-orange-500 animate-pulse shadow-[0_0_10px_rgba(249,115,22,0.5)]"></span>
                                        <span className="text-sm font-medium">{state.leadCard.status}</span>
                                    </div>
                                )}
                            </div>
                        </div>
                    </div>

                    {/* Success Footer */}
                    <div className={`bg-green-500/10 p-4 flex items-center justify-center gap-3 border-t border-green-500/20 transition-all duration-500 ${state.step === 'complete' ? 'opacity-100 translate-y-0' : 'opacity-0 translate-y-4'}`}>
                        <div className="w-6 h-6 bg-green-500 rounded-full flex items-center justify-center text-white shadow-lg shadow-green-500/30">
                            <CheckIcon className="w-4 h-4" />
                        </div>
                        <span className="text-sm font-bold text-green-700 dark:text-green-400">Lead Captured Automatically</span>
                    </div>
                </div>

            </div>
        </div>
    );
};
